"""Play cases with an agent against the arena over HTTP - the hosted arena (practice, sandbox,
final) or `arena-sim`, the local contract simulator. Both speak the same API.

An agent is any object with `decide(case, threads) -> {"supplier_id": ..., "message": {...}}`:
  threads: {supplier_id: [message, ...]} - every e-mail so far, both directions, in order;
           supplier attachments carry their text under "text" (see `docs.read_document`).
  message: subject, body, up to 3 term sheets, refs - or an "action" that closes the case:
           {"type": "accept", "term_sheet_id": ...} or {"type": "walk_away"}.
"""

import functools
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from . import runlog
from .client import ArenaError
from .cost import must_haves_ok, total_cost
from .docs import read_document, standard_terms

log = logging.getLogger("arena")

ENDED = {"walked_away", "no_bid"}
# A message later than this after the supplier's last one counts as a timeout.
MOVE_LIMIT_S = 60
# In the Live Final, close this long before the wave's cap - or the slowest round of the case so far
# (your decision plus a supplier reply of up to about a minute) plus a margin, if that is longer.
CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S = 90, 15
RUNNING = re.compile(r"one session per case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def case_file(self, case_id):
        """The case file before a session is opened (to prepare without the clock), or None."""
        if self.case:
            return self.case
        for case_set in ("practice", "sandbox"):
            try:
                found = next((c for c in self.client.cases(case_set) if c["case_id"] == case_id), None)
            except ArenaError:
                continue
            if found:
                return found
        return None

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        if (rec := runlog.current()) and reply.get("body"):
            rec.received(supplier_id, reply)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def offers(events):
    """Every term sheet of the supplier's latest message: [(term_sheet_id, terms)]. A supplier may
    send alternatives next to its standing offer (e.g. `offer:X-5` and `offer:X-5-a`); each can be
    accepted."""
    return [(s["term_sheet_id"], s["terms"]) for s in latest(events).get("term_sheets") or [] if s.get("terms")]


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def fetch_documents(table, message):
    """Download every attachment of a supplier message and add its text."""
    for att in message.get("attachments") or []:
        if att.get("attachment_id") and "text" not in att:
            data = table.attachment(att["attachment_id"])
            if rec := runlog.current():
                rec.attachment(att, data)
            att["text"] = read_document(att["name"], data)
    return message


def closing_move(case, threads):
    """Accept the cheapest standing term sheet that keeps the must-haves and beats the alternative
    (C with each supplier's standard terms), else walk away - what to do when time runs out."""
    alt = case["buyer"].get("alternative") or {}
    c_alt = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else float("inf")
    best = None
    for sid in live_threads(threads):
        std = standard_terms(threads[sid])
        for sheet_id, terms in offers(threads[sid]):  # alternatives count too
            if must_haves_ok(case, terms, std) and (c := total_cost(case, terms, std)) < c_alt:
                best = min(best or (c, sid, sheet_id), (c, sid, sheet_id))
    if best is None:
        return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}
    return {"supplier_id": best[1], "message": {"action": {"type": "accept", "term_sheet_id": best[2]}}}


def play(table, case_id, agent, deadline=None):
    """Play one case to its end. `deadline` (time.time(), or a function returning it): a Live Final
    wave's cap - shortly before it, `closing_move` closes the case so it does not end without a deal.
    Every e-mail, decision and API call goes into the run log (`runlog`)."""
    with runlog.case(case_id, agent, table) as rec:
        result = _play(table, case_id, agent, deadline, rec)
        if rec:
            rec.finish(result, table)
        return result


def _prime(table, case_id, agent):
    """An agent with `prime(case)` prepares before the session opens - before any clock runs."""
    if not hasattr(agent, "prime") or not hasattr(table, "case_file"):
        return
    try:
        case = table.case_file(case_id)
        if case:
            agent.prime(case)
    except Exception:  # preparing is a bonus; the agent primes itself again once the case is open
        log.exception("%s: preparing before the session failed", case_id)


def _send_all(table, decisions, rec):
    """Several e-mails at once, one per thread: [(decision, reply or ArenaError)], in order."""

    def one(d):
        with runlog.bind(rec):
            try:
                return table.send(d["supplier_id"], d["message"])
            except ArenaError as e:
                return e

    with ThreadPoolExecutor(max_workers=len(decisions)) as pool:
        return list(zip(decisions, pool.map(one, decisions), strict=True))


def _play(table, case_id, agent, deadline, rec):
    _prime(table, case_id, agent)
    case, threads = table.open(case_id)
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    if rec:
        rec.opened(getattr(table, "session_id", None), case, threads, resumed=bool(getattr(table, "done", None)))
    if getattr(table, "done", None):  # resumed a case that had already ended
        return table.done
    slowest = 0.0  # the longest round so far: decision + the supplier's reply
    while live_threads(threads):
        t0 = time.monotonic()
        cap = deadline() if callable(deadline) else deadline
        if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S):
            log.info("%s: the wave's cap is near - closing", case_id)
            decision, source = closing_move(case, threads), "closing_move"
        else:
            source = type(agent).__name__
            # An agent with `decide_all` may write to several threads at once (an RFQ: no thread
            # waits into the 60-second rule while another is answered).
            if hasattr(agent, "decide_all"):
                decisions = agent.decide_all(case, threads)
            else:
                decisions = [agent.decide(case, threads)]
            decision = next((d for d in decisions if d["message"].get("action")), decisions[0])
            if len(decisions) > 1 and not decision["message"].get("action"):
                took = time.monotonic() - t0
                for d in decisions:
                    if rec:
                        rec.decision(d, took, source)
                        rec.sent(d["supplier_id"], d["message"])
                for d, reply in _send_all(table, decisions, rec):
                    sid, msg = d["supplier_id"], d["message"]
                    if isinstance(reply, ArenaError):
                        if reply.status != 409:
                            raise reply
                        log.info("%s: %s", sid, reply.detail)
                        reply = table.missed(sid, reply)
                    if "result" in reply:  # the case has ended (e.g. at the cap)
                        if rec and reply.get("body"):
                            rec.received(sid, reply)
                        return reply["result"]
                    threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
                    if rec:
                        rec.received(sid, reply)
                    log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
                slowest = max(slowest, time.monotonic() - t0)
                continue
        if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
            log.warning("decision took %.1fs - the limit is %ss per message", took, MOVE_LIMIT_S)
        sid, msg = decision["supplier_id"], decision["message"]
        if rec:
            rec.decision(decision, took, source)
            rec.sent(sid, msg)
        try:
            if msg.get("action"):
                log.info("%s %s", sid, msg["action"])
                return table.close(sid, msg)
            reply = table.send(sid, msg)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)  # e.g. late, or the thread or the case has ended
            if msg.get("action") and "result" not in reply:  # the case goes on: decide again
                threads[sid].append(fetch_documents(table, reply))
                if rec:
                    rec.received(sid, reply)
                continue
        if "result" in reply:  # the reply ended the case, e.g. the last supplier walked away
            if rec and reply.get("body"):
                rec.received(sid, reply)
            return reply["result"]
        threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
        if rec:
            rec.received(sid, reply)
        slowest = max(slowest, time.monotonic() - t0)
        log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
    return table.result()


def hosted(cases):
    """The cases you can play: those marked hosted, or all of them if the list has no marker."""
    if any(HOSTED_FIELD in c for c in cases):
        return [c for c in cases if c.get(HOSTED_FIELD)]
    return cases


def quota_used_up(error):
    """The practice quota's 429 ("practice limit: …"): retrying does not help before it resets."""
    return isinstance(error, ArenaError) and error.status == 429 and str(error.detail).startswith("practice limit")


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Play many cases at once (e.g. every practice case). `new_table()` and `new_agent()` give
    each case its own table and agent. Once the practice quota is used up, no further case starts.
    Returns {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)  # e.g. not hosted for practice
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap, wait
    for the next. Keep it running from before the first wave until the last has closed; it returns
    after `waves` waves have closed and every case has finished: {case_id: result or exception}."""
    started, closed, caps = {}, set(), {}  # caps: wave -> its cap as time.time()

    def one(case, deadline):
        try:
            return play(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:  # each wave has its own cap; follow an extension
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}
"""Thin HTTP client for the arena API. Every method returns the JSON the server sends."""

import os
import threading
import time
import uuid

import httpx

from . import runlog

# Venue Wi-Fi drops. Retrying with the same move id makes the server return the reply it already
# gave instead of playing the move twice, so retries are safe even mid-negotiation.
MOVE_ID_HEADER = "X-Move-Id"
RETRY_STATUS = {429, 500, 502, 503, 504}
CALLS_PER_SECOND = 9  # the arena allows 10 per key; stay just below, across all threads
# A supplier's reply can take up to about a minute (its time does not count against your 60 s),
# and a call may wait for another call on the same session first: wait long enough for both.
TIMEOUT_S = 180.0
# Practice has a daily quota per team: every practice session start carries what is left in this
# header, and GET /v1/me tells where the team stands.
REMAINING_HEADER = "X-Practice-Remaining"
ME_PATH = "/me"
# A 429 with a short Retry-After is the per-second rate limit: wait and retry. Any other 429 (the
# practice quota, too many open sessions) does not go away by retrying.
MAX_RETRY_AFTER_S = 5


class ArenaError(Exception):
    def __init__(self, status: int, detail):
        super().__init__(f"HTTP {status}: {detail}")
        self.status, self.detail = status, detail


class ArenaClient:
    def __init__(
        self,
        base_url=None,
        api_key=None,
        *,
        retries=3,
        transport=None,
        timeout=TIMEOUT_S,
        rate=CALLS_PER_SECOND,
    ):
        base_url = (base_url or os.environ.get("ARENA_URL", "")).rstrip("/")
        if not base_url:
            raise ValueError("set ARENA_URL (e.g. https://…) or pass base_url")
        key = api_key or os.environ.get("ARENA_API_KEY")
        headers = {"X-API-Key": key} if key else {}
        self.retries, self.rate, self._lock, self._next = retries, rate, threading.Lock(), 0.0
        self.practice_remaining = None  # from the last practice reply that said so
        self.http = httpx.Client(base_url=f"{base_url}/v1", headers=headers, timeout=timeout, transport=transport)

    def _pace(self):
        with self._lock:
            now = time.monotonic()
            wait, self._next = self._next - now, max(now, self._next) + 1 / self.rate
        if wait > 0:
            time.sleep(wait)

    def _call(self, method, path, body=None, params=None, raw=False):
        headers = {MOVE_ID_HEADER: uuid.uuid4().hex} if method == "POST" else {}
        for attempt in range(self.retries + 1):
            self._pace()
            t0 = time.monotonic()
            try:
                r = self.http.request(method, path, json=body, params=params, headers=headers)
            except httpx.TransportError as e:
                self._log(method, path, params, body, None, f"{type(e).__name__}: {e}", t0, attempt, headers)
                if attempt == self.retries:
                    raise
                wait = None
            else:
                self._log(method, path, params, body, r.status_code, r, t0, attempt, headers, raw)
                wait = r.headers.get("Retry-After", "")
                short = wait.isdigit() and int(wait) <= MAX_RETRY_AFTER_S
                if r.status_code not in RETRY_STATUS or attempt == self.retries or (r.status_code == 429 and not short):
                    break
            time.sleep(float(wait) if wait and wait.isdigit() else 0.5 * 2**attempt)
        if (left := r.headers.get(REMAINING_HEADER, "")).isdigit():
            self.practice_remaining = int(left)
        if r.status_code >= 400:
            try:
                detail = r.json().get("detail", r.text)
            except (ValueError, AttributeError):
                detail = r.text
            raise ArenaError(r.status_code, detail)
        return r.content if raw else r.json()

    @staticmethod
    def _log(method, path, params, body, status, response, t0, attempt, headers, raw=False):
        """Every call into the run log (`runlog`): never the key, files only by size."""
        if isinstance(response, httpx.Response):
            if raw or status is None:
                response = {"bytes": len(response.content), "content_type": response.headers.get("content-type")}
            else:
                try:
                    response = response.json()
                except ValueError:
                    response = response.text
        runlog.http(
            method, path, params, body, status, response, time.monotonic() - t0, attempt, headers.get(MOVE_ID_HEADER)
        )

    def register(self, team_name, event_code):
        """arena-sim only: the simulator hands out its own keys. On the arena, the organisers
        give each team its key."""
        return self._call("POST", "/register", {"team_name": team_name, "event_code": event_code})

    def me(self):
        """Your team: practice sessions used and left, when the quota resets, best score per case."""
        return self._call("GET", ME_PATH)

    def cases(self, set_="practice"):
        return self._call("GET", "/cases", params={"set": set_})

    def open_session(self, case_id):
        return self._call("POST", "/sessions", {"case_id": case_id})

    def send_message(self, session_id, supplier_id, message):
        """Your e-mail to one supplier; returns its reply (or the result, if `action` closes)."""
        path = f"/sessions/{session_id}/threads/{supplier_id}/messages"
        return self._call("POST", path, {"message": message})

    def thread(self, session_id, supplier_id):
        return self._call("GET", f"/sessions/{session_id}/threads/{supplier_id}")

    def attachment(self, session_id, attachment_id):
        """The bytes of a document a supplier attached."""
        return self._call("GET", f"/sessions/{session_id}/attachments/{attachment_id}", raw=True)

    def backoffice(self, session_id):
        return self._call("GET", f"/sessions/{session_id}/backoffice")

    def move(self, session_id, supplier_id, move):
        body = {"supplier_id": supplier_id, "move": move}
        return self._call("POST", f"/sessions/{session_id}/moves", body)

    def accept(self, session_id, offer_id):
        return self._call("POST", f"/sessions/{session_id}/accept", {"offer_id": offer_id})

    def walk_away(self, session_id):
        return self._call("POST", f"/sessions/{session_id}/walk_away")

    def session(self, session_id):
        return self._call("GET", f"/sessions/{session_id}")

    def sessions(self, set_="practice"):
        return self._call("GET", "/sessions", params={"set": set_})

    def leaderboard(self, set_="practice"):
        return self._call("GET", "/leaderboard", params={"set": set_})

    def downloads(self):
        """The data you can download: the package, and the Sunday release once it is public."""
        return self._call("GET", "/data")

    def download(self, name):
        """A data download (zip bytes), e.g. "package" or "release-sunday"."""
        return self._call("GET", f"/data/{name}.zip", raw=True)

content.content:
"""What the data says about one supplier: the dossier code gathers before a case opens.

The case file points to a handful of facts; the supplier's real situation sits in the rest of the
package - call and meeting notes, letters, past negotiations, its financials, our payment record,
its scorecards, the cost structure of the part. `gather` collects all of it for one supplier and
the case's parts, `render` turns it into text a language model reads once, before the clock runs.
Built on `DataPackage`, so the Sunday release is included.
"""

import json
import re
import threading

CASH_WORDS = re.compile(
    r"\b(cash|liquidity|pay(?:ing)? our invoices|within \d+ days|cash discount|skonto|prepay|advance payment|"
    r"short[- ]time work|insolven|bank|credit line|working capital)\b",
    re.I,
)
_cache, _lock = {}, threading.Lock()


def _q(package, sql, params=()):
    try:
        return package.query(sql, params)
    except Exception:  # a package without SQLite, or a table this release does not have
        return []


def _text(package, ref, limit):
    try:
        text = package.document(ref)
    except (FileNotFoundError, ValueError, KeyError):
        return ""
    lines = [ln for ln in text.splitlines() if ln.strip() and not ln.startswith("# ")]
    return re.sub(r"\s+", " ", " ".join(lines)).strip()[:limit]


def gather(package, case, sid):
    """Everything about `sid` and the case's parts, as {section: rows}. Cached per supplier and parts."""
    parts = tuple(case.get("parts", []))
    key = (sid, parts, case.get("trigger_doc"))
    with _lock:
        if key in _cache:
            return _cache[key]
    d = {"supplier_id": sid}
    if package is not None:
        d.update(_from_package(package, case, sid, parts))
    # Hidden cases carry facts that exist only in the case (e.g. a new letter).
    d["case_facts"] = {k: v for k, v in (case.get("facts") or {}).items() if sid in json.dumps(v)}
    text = " ".join(str(r.get("text", "")) for r in d.get("correspondence", []))
    intel = (d.get("intel") or [{}])[0]
    eq, ci, ci0 = intel.get("equity_ratio_pct"), intel.get("credit_index"), intel.get("credit_index_12m_ago")
    d["cash_signals"] = sorted(
        {m.group(0).lower() for m in CASH_WORDS.finditer(text)}
        | ({f"equity ratio {eq}%"} if isinstance(eq, int | float) and eq < 20 else set())
        | (
            {f"credit index worsened {ci0}->{ci}"}
            if isinstance(ci, int | float) and isinstance(ci0, int | float) and ci - ci0 >= 15
            else set()
        )
    )
    with _lock:
        _cache[key] = d
    return d


def _from_package(package, case, sid, parts):
    marks = ",".join("?" * len(parts)) or "''"
    d = {
        "supplier": _q(
            package,
            "SELECT id, name, country, payment_days, skonto_days, skonto_pct, incoterm, "
            "category, standard_lead_time_days, abc_class, contract_id FROM suppliers WHERE id = ?",
            (sid,),
        ),
        "intel": _q(package, "SELECT * FROM supplier_intel WHERE supplier_id = ?", (sid,)),
        "sourcing": _q(package, f"SELECT * FROM sourcing WHERE part_id IN ({marks})", parts),
        "parts": _q(
            package,
            f"SELECT id, description, category, material_group, net_weight_kg, price_unit, "
            f"standard_price, abc_class FROM parts WHERE id IN ({marks})",
            parts,
        ),
        "scorecards": _q(
            package,
            "SELECT id, quarter, otd_pct, ppm, qn_count, open_8d_overdue, score, colour "
            "FROM scorecards WHERE supplier_id = ? ORDER BY quarter DESC LIMIT 4",
            (sid,),
        ),
        "history": _q(
            package,
            "SELECT date, part_id, type, asked_pct, settled_pct, note FROM negotiation_history "
            "WHERE supplier_id = ? ORDER BY date DESC LIMIT 12",
            (sid,),
        ),
        "price_conditions": _q(
            package,
            f"SELECT part_id, valid_from, valid_to, price, basis FROM price_conditions "
            f"WHERE supplier_id = ? AND part_id IN ({marks}) ORDER BY valid_from DESC LIMIT 6",
            (sid, *parts),
        ),
        "quotes": _q(
            package,
            f"SELECT id, supplier_id, part_id, quote_date, unit_price, lead_time_days, incoterm, "
            f"payment_days, tooling_eur, awarded, remarks FROM quotes WHERE part_id IN ({marks}) "
            f"ORDER BY quote_date DESC LIMIT 10",
            parts,
        ),
        "should_cost": _q(package, f"SELECT * FROM should_cost WHERE part_id IN ({marks})", parts),
        "cost_drivers": _q(
            package, f"SELECT part_id, series_id, weight FROM cost_drivers WHERE part_id IN ({marks})", parts
        ),
        "news": _q(
            package,
            "SELECT id, date, topic, headline, body FROM news WHERE supplier_id = ? ORDER BY date DESC LIMIT 6",
            (sid,),
        ),
        "quality": _q(
            package,
            f"SELECT count(*) AS notifications, sum(complaint_qty) AS complaints, "
            f"sum(cost_recharged_eur) AS recharged_eur, max(qn_date) AS last FROM quality_notifications "
            f"WHERE supplier_id = ? AND part_id IN ({marks}) AND qn_date >= '2025-10-01'",
            (sid, *parts),
        ),
        "payments": _q(
            package,
            "SELECT count(*) AS invoices, round(avg(julianday(paid_date) - julianday(invoice_date)), 1) "
            "AS days_to_pay, round(avg(julianday(paid_date) - julianday(due_date)), 1) AS days_late, "
            "round(avg(discount_taken), 2) AS discount_share FROM invoices WHERE supplier_id = ? "
            "AND invoice_date >= '2025-10-01'",
            (sid,),
        ),
        "forecast": _q(
            package,
            f"SELECT id, part_id, snapshot_month, qty_next_12m FROM forecasts WHERE part_id IN "
            f"({marks}) ORDER BY snapshot_month DESC LIMIT 2",
            parts,
        ),
    }
    ctr = next((r["contract_id"] for r in d["supplier"] if r.get("contract_id")), None)
    d["contract"] = (
        _q(
            package,
            "SELECT id, type, valid_from, valid_to, payment_days, incoterm, notice_days, price_basis "
            "FROM contracts WHERE id = ?",
            (ctr,),
        )
        if ctr
        else []
    )
    d["clauses"] = _q(package, "SELECT id, text FROM contract_clauses WHERE contract_id = ?", (ctr,)) if ctr else []
    docs = _q(
        package,
        "SELECT id, date, kind, subject, asked_pct, asked_price, effective_date, notice_days "
        "FROM documents WHERE supplier_id = ? ORDER BY date DESC LIMIT 18",
        (sid,),
    )
    seen = {r["id"] for r in docs}
    # The Sunday release is CSV only: its letters and news are found by ID, not by SQL.
    for ref, row in getattr(package, "_ids", {}).items() if package.release else []:
        if row.get("root") and row.get("supplier_id") == sid and ref not in seen:
            docs.append({k: row.get(k) for k in ("id", "date", "kind", "subject", "topic", "headline")})
    trigger = case.get("trigger_doc")
    for r in docs:
        r["text"] = _text(package, r["id"], 2500 if r["id"] == trigger else 420)
    d["correspondence"] = sorted(docs, key=lambda r: str(r.get("date")), reverse=True)
    return d


def _rows(rows, skip=()):
    return "\n".join(
        "  "
        + json.dumps(
            {k: v for k, v in r.items() if v not in (None, "") and k not in skip}, ensure_ascii=False, default=str
        )
        for r in rows
    )


def render(d):
    """The dossier as text, newest first, for one language-model read."""
    out = [f"SUPPLIER {d['supplier_id']}"]
    for title, key in (
        ("Master data", "supplier"),
        ("Company (filed accounts, credit index: higher is worse)", "intel"),
        ("Contract", "contract"),
        ("Contract clauses", "clauses"),
        ("Scorecards, newest first", "scorecards"),
        ("Past negotiations with us (asked vs settled %)", "history"),
        ("Our price conditions", "price_conditions"),
        ("Quotes for these parts (all suppliers)", "quotes"),
        ("Should-cost estimates (no margin)", "should_cost"),
        ("Cost drivers of the part (index series, weight)", "cost_drivers"),
        ("Who else can make the part", "sourcing"),
        ("Parts", "parts"),
        ("News", "news"),
        ("Quality last 12 months", "quality"),
        ("How we paid them last 12 months", "payments"),
        ("Demand forecast", "forecast"),
    ):
        if d.get(key):
            out.append(f"{title}:\n{_rows(d[key])}")
    if d.get("correspondence"):
        out.append("Correspondence, call and meeting notes (newest first):")
        for r in d["correspondence"]:
            out.append(
                f"  [{r.get('date')} {r.get('kind') or ''} {r['id']}] {r.get('subject') or r.get('headline') or ''}: "
                f"{r.get('text', '')}"
            )
    if d.get("case_facts"):
        out.append(
            f"Facts only this case has:\n  {json.dumps(d['case_facts'], ensure_ascii=False, default=str)[:3000]}"
        )
    if d.get("cash_signals"):
        out.append(f"Cash signals found: {', '.join(d['cash_signals'])}")
    return "\n".join(out)
"""Data arguments that check out: sentences with a figure and its IDs, computed from the facts.

The arena checks every cited ID against `facts.json` (api.md, "What counts"): an index change over
two months of one series, at most 12 months apart, ending within the last 12 months of the data; a
quote's or a rival offer's price; a scorecard's on-time delivery or ppm; a should-cost estimate; a
forecast change; a letter's notice against the contract's. Here code computes each figure the way
the arena does and writes one sentence per argument - the language model only chooses among them,
and they go into the e-mail word for word. Each ID counts once per case (a rival's quote once per
supplier), so `Ledger` remembers what has been cited.
"""

import re
from dataclasses import dataclass, field

DATA_END = "2026-09"  # the data is frozen at 2026-09-30


@dataclass
class Claim:
    key: str  # stable across rounds, e.g. "index:PPI-D351"
    kind: str
    ids: list
    sentence: str
    favourable: bool = True  # False: true, but it argues the supplier's side
    note: str = ""  # for the model: why it matters
    figure: float | None = None
    strength: float = 1.0  # how hard it argues our case: ranks the arguments when no profile does
    extra: list = field(default_factory=list)  # context sentences without IDs, sent with the claim


class Ledger:
    """What has been cited in this case, and how each citation checked out."""

    def __init__(self):
        self.used, self.results = set(), {}

    def spent(self, claim, sid):
        return any(self._key(i, sid) in self.used for i in claim.ids)

    def use(self, claim, sid):
        for i in claim.ids:
            self.used.add(self._key(i, sid))

    @staticmethod
    def _key(ref, sid):
        return (sid, ref) if ref.startswith(("quote:", "offer:")) else ref


def _fact(package, case, ref):
    return (case.get("facts") or {}).get(ref) or (package.lookup(ref) if package else None)


def _month_minus(month, n):
    y, m = map(int, month.split("-"))
    m -= n
    while m <= 0:
        y, m = y - 1, m + 12
    return f"{y}-{m:02d}"


def series_name(package, series):
    row = package.lookup(series) if package else None
    name = ""
    if package and not row:
        rows = package.query("SELECT name FROM index_series WHERE id = ?", (series,)) if package.db else []
        name = rows[0]["name"] if rows else ""
    name = name or (row or {}).get("name") or ""
    if m := re.match(r"Producer prices DE: (.+)", name):
        return f"German producer prices for {m.group(1)}"
    if name.startswith("Labour cost index DE"):
        return "The German labour cost index for manufacturing"
    if m := re.match(r"(Copper|Nickel|Aluminium|Iron ore), monthly", name):
        return f"The {m.group(1).lower()} price"
    if name.startswith("Natural gas Europe"):
        return "The European natural gas price"
    if name.startswith("Day-ahead power price"):
        return "The German day-ahead power price"
    if m := re.match(r"Alloy surcharge ([\d.]+)", name):
        return f"The alloy surcharge for {m.group(1)}"
    if name.startswith("Copper notation"):
        return "The copper notation"
    return f"The {series} index"


def index_change(package, case, series, end=None):
    """(change %, earlier id, later id) over the last 12 months the data has, or None."""
    ids = sorted(
        set(package.ids(f"idx:{series}@") if package else [])
        | {k for k in (case.get("facts") or {}) if k.startswith(f"idx:{series}@")}
    )
    ids = [i for i in ids if i.split("@")[1] <= (end or DATA_END)]
    if not ids:
        return None
    later = ids[-1]
    month = later.split("@")[1]
    if month < _month_minus(DATA_END, 11):
        return None  # too old: the arena reads it as irrelevant
    earlier = f"idx:{series}@{_month_minus(month, 12)}"
    a, b = _fact(package, case, earlier), _fact(package, case, later)
    if not (a and b and a.get("value") and b.get("value") is not None):
        return None
    return round((b["value"] / a["value"] - 1) * 100, 1), earlier, later


def candidates(package, case, sid, their_price=None, rivals=None):
    """Every argument the data gives for this supplier, best first within each kind.
    `their_price`: the supplier's standing unit price; `rivals`: {offer_id: unit price} of the other
    suppliers in this session."""
    out = []
    parts = case.get("parts", [])
    trigger = _fact(package, case, case["trigger_doc"]) if case.get("trigger_doc") else None
    asked = (trigger or {}).get("asked_pct")

    # 1. The index series that drive the part's cost (or that a clause would follow).
    weights = {}
    if package and package.db:
        for p in parts:
            for r in package.query("SELECT series_id, weight FROM cost_drivers WHERE part_id = ?", (p,)):
                weights[r["series_id"]] = max(weights.get(r["series_id"], 0), r["weight"] or 0)
    for opt in case.get("term_options", {}).get("index_clause", []) or []:
        if opt:
            weights.setdefault(opt["series"], opt.get("material_share", 0))
    for ref in case.get("refs", []):
        if ref.startswith("idx:"):
            weights.setdefault(ref[4:].split("@")[0], 0)
    impact = 0.0
    for series, w in sorted(weights.items(), key=lambda kv: -kv[1]):
        got = index_change(package, case, series)
        if not got:
            continue
        chg, a, b = got
        impact += w * chg
        fav = chg <= 1.0 or (asked is not None and chg < asked / 2)
        out.append(
            Claim(
                key=f"index:{series}",
                kind="index",
                ids=[a, b],
                figure=chg,
                favourable=fav,
                sentence=f"{series_name(package, series)} changed {chg:+.1f}% "
                f"from {a.split('@')[1]} to {b.split('@')[1]} ({a}, {b}).",
                note=f"weight {w:.0%} in the part's cost" if w else "",
                strength=max(0.0, (w or 0.1) * ((asked or 0) - chg)) if asked else max(0.0, -(w or 0.1) * chg),
            )
        )
    if weights and asked:
        out.append(
            Claim(
                key="summary:indices",
                kind="summary",
                ids=[],
                figure=round(impact, 1),
                favourable=impact < asked,
                sentence=f"Weighted with the cost structure of this part, the index movements explain about "
                f"{impact:+.1f}% on the price - not {asked:g}%.",
                note="no ID: our own reasoning, not a checked claim",
            )
        )

    # 2. A letter that gives less notice than the contract requires.
    if trigger and trigger.get("days") is not None:
        ctr = next((r for r in case.get("refs", []) if r.startswith("ctr:") and "#" not in r), None)
        cf = _fact(package, case, ctr) if ctr else None
        if cf and cf.get("days") and trigger["days"] < cf["days"]:
            out.append(
                Claim(
                    key="notice",
                    kind="notice",
                    ids=[case["trigger_doc"], ctr],
                    figure=trigger["days"],
                    sentence=f"Your letter gives us only {trigger['days']} days of notice "
                    f"({case['trigger_doc']}, {ctr}).",
                    extra=[f"Our contract requires {cf['days']} days."],
                    note="the increase cannot take effect as announced",
                    strength=5.0,
                )
            )

    # 3. Delivery and quality record.
    sc = sorted(
        i
        for i in ([*case.get("refs", [])] + (package.ids(f"sc:{sid.split(':')[1]}@") if package else []))
        if i.startswith(f"sc:{sid.split(':')[1]}@")
    )
    if sc and (row := _fact(package, case, sc[-1])):
        if case.get("type") == "quality" or (row.get("ppm") or 0) >= 1000:
            out.append(
                Claim(
                    key="scorecard",
                    kind="quality",
                    ids=[sc[-1]],
                    figure=row.get("ppm"),
                    favourable=(row.get("ppm") or 0) > 300,
                    sentence=f"Your defect rate over the last four quarters stands at {row.get('ppm')} ppm ({sc[-1]}).",
                    strength=3.0 if case.get("type") == "quality" else 1.0,
                )
            )
        elif row.get("otd_pct") is not None:
            out.append(
                Claim(
                    key="scorecard",
                    kind="delivery",
                    ids=[sc[-1]],
                    figure=row["otd_pct"],
                    favourable=row["otd_pct"] < 95,
                    sentence=f"Your on-time delivery over the last four quarters was {row['otd_pct']:.1f}% ({sc[-1]}).",
                    strength=(95 - row["otd_pct"]) / 5,
                )
            )

    # 4. Competing prices: a rival's offer in this session, or a quote the case points to.
    for oid, price in sorted((rivals or {}).items(), key=lambda kv: kv[1]):
        if their_price is None or price < their_price:
            out.append(
                Claim(
                    key=f"rival:{oid.split('-')[0]}",
                    kind="rival",
                    ids=[oid],
                    figure=price,
                    sentence=f"We hold a competing offer at EUR {price:.2f} per unit ({oid}).",
                    note="reveals that rival's price to this supplier",
                    strength=6.0,
                )
            )
            break
    alt = (case.get("buyer") or {}).get("alternative") or {}
    for ref in [alt.get("ref")] + [r for r in case.get("refs", []) if r.startswith("quote:")]:
        q = _fact(package, case, ref) if ref and ref.startswith("quote:") else None
        if q and q.get("supplier") != sid and q.get("unit_price") and q.get("part") in parts:
            fav = their_price is not None and q["unit_price"] < their_price
            out.append(
                Claim(
                    key=f"quote:{ref}",
                    kind="rival",
                    ids=[ref],
                    figure=q["unit_price"],
                    favourable=fav,
                    sentence=f"We hold a quote from another qualified supplier at EUR {q['unit_price']:.2f} "
                    f"per unit ({ref}).",
                    note="" if fav else "higher than this supplier's price: citing it would weaken us",
                    strength=4.0,
                )
            )
            break

    # 5. Should-cost: only when it leaves the supplier a healthy margin at a lower price.
    for p in parts:
        ref = f"cost:{p.split(':')[1]}"
        if (row := _fact(package, case, ref)) and row.get("unit_cost") and their_price:
            fav = row["unit_cost"] * 1.08 < their_price
            out.append(
                Claim(
                    key="should_cost",
                    kind="should_cost",
                    ids=[ref],
                    figure=row["unit_cost"],
                    favourable=fav,
                    sentence=f"Our should-cost estimate for this part is EUR {row['unit_cost']:.2f} per unit ({ref}).",
                    note="no margin included" if fav else "close to their price: shows they earn little - avoid",
                    strength=3.0,
                )
            )

    # 6. Volume: a growing forecast is a reason to want our business.
    if package:
        for p in parts:
            fcs = package.ids(f"fc:{p.split(':')[1]}@")
            if fcs and (row := _fact(package, case, fcs[-1])) and row.get("change_pct") is not None:
                # Only as growth if the volume did grow: P01's +10.1% sat next to a forecast that fell
                # from 8,200 to 8,150 - a supplier who sees both reads it as overstated.
                before = _fact(package, case, fcs[-2]) if len(fcs) > 1 else None
                grew = not before or (row.get("volume_per_year") or 0) >= (before.get("volume_per_year") or 0)
                out.append(
                    Claim(
                        key="forecast",
                        kind="volume",
                        ids=[fcs[-1]],
                        figure=row["change_pct"],
                        favourable=row["change_pct"] > 0 and grew,
                        sentence=f"Our demand forecast for this part has changed "
                        f"{row['change_pct']:+.1f}% ({fcs[-1]}).",
                        note="growing volume: a carrot, not a threat",
                        strength=1.5,
                    )
                )

    # 7. News about the supplier: true by ID; the model judges whether it helps.
    if package and package.db:
        for r in package.query(
            "SELECT id, headline, topic FROM news WHERE supplier_id = ? ORDER BY date DESC LIMIT 3", (sid,)
        ):
            out.append(
                Claim(
                    key=f"news:{r['id']}",
                    kind="news",
                    ids=[r["id"]],
                    favourable=False,
                    sentence=f"We have followed the news about your company ({r['id']}).",
                    note=f"{r['topic']}: {r['headline']}",
                )
            )
    out.sort(key=lambda c: -c.strength)
    return out


def usable(claims, ledger, sid):
    """The favourable claims not cited yet."""
    return [c for c in claims if c.favourable and not ledger.spent(c, sid)]

toolUseResult.stdout:
"""What the data says about one supplier: the dossier code gathers before a case opens.

The case file points to a handful of facts; the supplier's real situation sits in the rest of the
package - call and meeting notes, letters, past negotiations, its financials, our payment record,
its scorecards, the cost structure of the part. `gather` collects all of it for one supplier and
the case's parts, `render` turns it into text a language model reads once, before the clock runs.
Built on `DataPackage`, so the Sunday release is included.
"""

import json
import re
import threading

CASH_WORDS = re.compile(
    r"\b(cash|liquidity|pay(?:ing)? our invoices|within \d+ days|cash discount|skonto|prepay|advance payment|"
    r"short[- ]time work|insolven|bank|credit line|working capital)\b",
    re.I,
)
_cache, _lock = {}, threading.Lock()


def _q(package, sql, params=()):
    try:
        return package.query(sql, params)
    except Exception:  # a package without SQLite, or a table this release does not have
        return []


def _text(package, ref, limit):
    try:
        text = package.document(ref)
    except (FileNotFoundError, ValueError, KeyError):
        return ""
    lines = [ln for ln in text.splitlines() if ln.strip() and not ln.startswith("# ")]
    return re.sub(r"\s+", " ", " ".join(lines)).strip()[:limit]


def gather(package, case, sid):
    """Everything about `sid` and the case's parts, as {section: rows}. Cached per supplier and parts."""
    parts = tuple(case.get("parts", []))
    key = (sid, parts, case.get("trigger_doc"))
    with _lock:
        if key in _cache:
            return _cache[key]
    d = {"supplier_id": sid}
    if package is not None:
        d.update(_from_package(package, case, sid, parts))
    # Hidden cases carry facts that exist only in the case (e.g. a new letter).
    d["case_facts"] = {k: v for k, v in (case.get("facts") or {}).items() if sid in json.dumps(v)}
    text = " ".join(str(r.get("text", "")) for r in d.get("correspondence", []))
    intel = (d.get("intel") or [{}])[0]
    eq, ci, ci0 = intel.get("equity_ratio_pct"), intel.get("credit_index"), intel.get("credit_index_12m_ago")
    d["cash_signals"] = sorted(
        {m.group(0).lower() for m in CASH_WORDS.finditer(text)}
        | ({f"equity ratio {eq}%"} if isinstance(eq, int | float) and eq < 20 else set())
        | (
            {f"credit index worsened {ci0}->{ci}"}
            if isinstance(ci, int | float) and isinstance(ci0, int | float) and ci - ci0 >= 15
            else set()
        )
    )
    with _lock:
        _cache[key] = d
    return d


def _from_package(package, case, sid, parts):
    marks = ",".join("?" * len(parts)) or "''"
    d = {
        "supplier": _q(
            package,
            "SELECT id, name, country, payment_days, skonto_days, skonto_pct, incoterm, "
            "category, standard_lead_time_days, abc_class, contract_id FROM suppliers WHERE id = ?",
            (sid,),
        ),
        "intel": _q(package, "SELECT * FROM supplier_intel WHERE supplier_id = ?", (sid,)),
        "sourcing": _q(package, f"SELECT * FROM sourcing WHERE part_id IN ({marks})", parts),
        "parts": _q(
            package,
            f"SELECT id, description, category, material_group, net_weight_kg, price_unit, "
            f"standard_price, abc_class FROM parts WHERE id IN ({marks})",
            parts,
        ),
        "scorecards": _q(
            package,
            "SELECT id, quarter, otd_pct, ppm, qn_count, open_8d_overdue, score, colour "
            "FROM scorecards WHERE supplier_id = ? ORDER BY quarter DESC LIMIT 4",
            (sid,),
        ),
        "history": _q(
            package,
            "SELECT date, part_id, type, asked_pct, settled_pct, note FROM negotiation_history "
            "WHERE supplier_id = ? ORDER BY date DESC LIMIT 12",
            (sid,),
        ),
        "price_conditions": _q(
            package,
            f"SELECT part_id, valid_from, valid_to, price, basis FROM price_conditions "
            f"WHERE supplier_id = ? AND part_id IN ({marks}) ORDER BY valid_from DESC LIMIT 6",
            (sid, *parts),
        ),
        "quotes": _q(
            package,
            f"SELECT id, supplier_id, part_id, quote_date, unit_price, lead_time_days, incoterm, "
            f"payment_days, tooling_eur, awarded, remarks FROM quotes WHERE part_id IN ({marks}) "
            f"ORDER BY quote_date DESC LIMIT 10",
            parts,
        ),
        "should_cost": _q(package, f"SELECT * FROM should_cost WHERE part_id IN ({marks})", parts),
        "cost_drivers": _q(
            package, f"SELECT part_id, series_id, weight FROM cost_drivers WHERE part_id IN ({marks})", parts
        ),
        "news": _q(
            package,
            "SELECT id, date, topic, headline, body FROM news WHERE supplier_id = ? ORDER BY date DESC LIMIT 6",
            (sid,),
        ),
        "quality": _q(
            package,
            f"SELECT count(*) AS notifications, sum(complaint_qty) AS complaints, "
            f"sum(cost_recharged_eur) AS recharged_eur, max(qn_date) AS last FROM quality_notifications "
            f"WHERE supplier_id = ? AND part_id IN ({marks}) AND qn_date >= '2025-10-01'",
            (sid, *parts),
        ),
        "payments": _q(
            package,
            "SELECT count(*) AS invoices, round(avg(julianday(paid_date) - julianday(invoice_date)), 1) "
            "AS days_to_pay, round(avg(julianday(paid_date) - julianday(due_date)), 1) AS days_late, "
            "round(avg(discount_taken), 2) AS discount_share FROM invoices WHERE supplier_id = ? "
            "AND invoice_date >= '2025-10-01'",
            (sid,),
        ),
        "forecast": _q(
            package,
            f"SELECT id, part_id, snapshot_month, qty_next_12m FROM forecasts WHERE part_id IN "
            f"({marks}) ORDER BY snapshot_month DESC LIMIT 2",
            parts,
        ),
    }
    ctr = next((r["contract_id"] for r in d["supplier"] if r.get("contract_id")), None)
    d["contract"] = (
        _q(
            package,
            "SELECT id, type, valid_from, valid_to, payment_days, incoterm, notice_days, price_basis "
            "FROM contracts WHERE id = ?",
            (ctr,),
        )
        if ctr
        else []
    )
    d["clauses"] = _q(package, "SELECT id, text FROM contract_clauses WHERE contract_id = ?", (ctr,)) if ctr else []
    docs = _q(
        package,
        "SELECT id, date, kind, subject, asked_pct, asked_price, effective_date, notice_days "
        "FROM documents WHERE supplier_id = ? ORDER BY date DESC LIMIT 18",
        (sid,),
    )
    seen = {r["id"] for r in docs}
    # The Sunday release is CSV only: its letters and news are found by ID, not by SQL.
    for ref, row in getattr(package, "_ids", {}).items() if package.release else []:
        if row.get("root") and row.get("supplier_id") == sid and ref not in seen:
            docs.append({k: row.get(k) for k in ("id", "date", "kind", "subject", "topic", "headline")})
    trigger = case.get("trigger_doc")
    for r in docs:
        r["text"] = _text(package, r["id"], 2500 if r["id"] == trigger else 420)
    d["correspondence"] = sorted(docs, key=lambda r: str(r.get("date")), reverse=True)
    return d


def _rows(rows, skip=()):
    return "\n".join(
        "  "
        + json.dumps(
            {k: v for k, v in r.items() if v not in (None, "") and k not in skip}, ensure_ascii=False, default=str
        )
        for r in rows
    )


def render(d):
    """The dossier as text, newest first, for one language-model read."""
    out = [f"SUPPLIER {d['supplier_id']}"]
    for title, key in (
        ("Master data", "supplier"),
        ("Company (filed accounts, credit index: higher is worse)", "intel"),
        ("Contract", "contract"),
        ("Contract clauses", "clauses"),
        ("Scorecards, newest first", "scorecards"),
        ("Past negotiations with us (asked vs settled %)", "history"),
        ("Our price conditions", "price_conditions"),
        ("Quotes for these parts (all suppliers)", "quotes"),
        ("Should-cost estimates (no margin)", "should_cost"),
        ("Cost drivers of the part (index series, weight)", "cost_drivers"),
        ("Who else can make the part", "sourcing"),
        ("Parts", "parts"),
        ("News", "news"),
        ("Quality last 12 months", "quality"),
        ("How we paid them last 12 months", "payments"),
        ("Demand forecast", "forecast"),
    ):
        if d.get(key):
            out.append(f"{title}:\n{_rows(d[key])}")
    if d.get("correspondence"):
        out.append("Correspondence, call and meeting notes (newest first):")
        for r in d["correspondence"]:
            out.append(
                f"  [{r.get('date')} {r.get('kind') or ''} {r['id']}] {r.get('subject') or r.get('headline') or ''}: "
                f"{r.get('text', '')}"
            )
    if d.get("case_facts"):
        out.append(
            f"Facts only this case has:\n  {json.dumps(d['case_facts'], ensure_ascii=False, default=str)[:3000]}"
        )
    if d.get("cash_signals"):
        out.append(f"Cash signals found: {', '.join(d['cash_signals'])}")
    return "\n".join(out)
"""Data arguments that check out: sentences with a figure and its IDs, computed from the facts.

The arena checks every cited ID against `facts.json` (api.md, "What counts"): an index change over
two months of one series, at most 12 months apart, ending within the last 12 months of the data; a
quote's or a rival offer's price; a scorecard's on-time delivery or ppm; a should-cost estimate; a
forecast change; a letter's notice against the contract's. Here code computes each figure the way
the arena does and writes one sentence per argument - the language model only chooses among them,
and they go into the e-mail word for word. Each ID counts once per case (a rival's quote once per
supplier), so `Ledger` remembers what has been cited.
"""

import re
from dataclasses import dataclass, field

DATA_END = "2026-09"  # the data is frozen at 2026-09-30


@dataclass
class Claim:
    key: str  # stable across rounds, e.g. "index:PPI-D351"
    kind: str
    ids: list
    sentence: str
    favourable: bool = True  # False: true, but it argues the supplier's side
    note: str = ""  # for the model: why it matters
    figure: float | None = None
    strength: float = 1.0  # how hard it argues our case: ranks the arguments when no profile does
    extra: list = field(default_factory=list)  # context sentences without IDs, sent with the claim


class Ledger:
    """What has been cited in this case, and how each citation checked out."""

    def __init__(self):
        self.used, self.results = set(), {}

    def spent(self, claim, sid):
        return any(self._key(i, sid) in self.used for i in claim.ids)

    def use(self, claim, sid):
        for i in claim.ids:
            self.used.add(self._key(i, sid))

    @staticmethod
    def _key(ref, sid):
        return (sid, ref) if ref.startswith(("quote:", "offer:")) else ref


def _fact(package, case, ref):
    return (case.get("facts") or {}).get(ref) or (package.lookup(ref) if package else None)


def _month_minus(month, n):
    y, m = map(int, month.split("-"))
    m -= n
    while m <= 0:
        y, m = y - 1, m + 12
    return f"{y}-{m:02d}"


def series_name(package, series):
    row = package.lookup(series) if package else None
    name = ""
    if package and not row:
        rows = package.query("SELECT name FROM index_series WHERE id = ?", (series,)) if package.db else []
        name = rows[0]["name"] if rows else ""
    name = name or (row or {}).get("name") or ""
    if m := re.match(r"Producer prices DE: (.+)", name):
        return f"German producer prices for {m.group(1)}"
    if name.startswith("Labour cost index DE"):
        return "The German labour cost index for manufacturing"
    if m := re.match(r"(Copper|Nickel|Aluminium|Iron ore), monthly", name):
        return f"The {m.group(1).lower()} price"
    if name.startswith("Natural gas Europe"):
        return "The European natural gas price"
    if name.startswith("Day-ahead power price"):
        return "The German day-ahead power price"
    if m := re.match(r"Alloy surcharge ([\d.]+)", name):
        return f"The alloy surcharge for {m.group(1)}"
    if name.startswith("Copper notation"):
        return "The copper notation"
    return f"The {series} index"


def index_change(package, case, series, end=None):
    """(change %, earlier id, later id) over the last 12 months the data has, or None."""
    ids = sorted(
        set(package.ids(f"idx:{series}@") if package else [])
        | {k for k in (case.get("facts") or {}) if k.startswith(f"idx:{series}@")}
    )
    ids = [i for i in ids if i.split("@")[1] <= (end or DATA_END)]
    if not ids:
        return None
    later = ids[-1]
    month = later.split("@")[1]
    if month < _month_minus(DATA_END, 11):
        return None  # too old: the arena reads it as irrelevant
    earlier = f"idx:{series}@{_month_minus(month, 12)}"
    a, b = _fact(package, case, earlier), _fact(package, case, later)
    if not (a and b and a.get("value") and b.get("value") is not None):
        return None
    return round((b["value"] / a["value"] - 1) * 100, 1), earlier, later


def candidates(package, case, sid, their_price=None, rivals=None):
    """Every argument the data gives for this supplier, best first within each kind.
    `their_price`: the supplier's standing unit price; `rivals`: {offer_id: unit price} of the other
    suppliers in this session."""
    out = []
    parts = case.get("parts", [])
    trigger = _fact(package, case, case["trigger_doc"]) if case.get("trigger_doc") else None
    asked = (trigger or {}).get("asked_pct")

    # 1. The index series that drive the part's cost (or that a clause would follow).
    weights = {}
    if package and package.db:
        for p in parts:
            for r in package.query("SELECT series_id, weight FROM cost_drivers WHERE part_id = ?", (p,)):
                weights[r["series_id"]] = max(weights.get(r["series_id"], 0), r["weight"] or 0)
    for opt in case.get("term_options", {}).get("index_clause", []) or []:
        if opt:
            weights.setdefault(opt["series"], opt.get("material_share", 0))
    for ref in case.get("refs", []):
        if ref.startswith("idx:"):
            weights.setdefault(ref[4:].split("@")[0], 0)
    impact = 0.0
    for series, w in sorted(weights.items(), key=lambda kv: -kv[1]):
        got = index_change(package, case, series)
        if not got:
            continue
        chg, a, b = got
        impact += w * chg
        fav = chg <= 1.0 or (asked is not None and chg < asked / 2)
        out.append(
            Claim(
                key=f"index:{series}",
                kind="index",
                ids=[a, b],
                figure=chg,
                favourable=fav,
                sentence=f"{series_name(package, series)} changed {chg:+.1f}% "
                f"from {a.split('@')[1]} to {b.split('@')[1]} ({a}, {b}).",
                note=f"weight {w:.0%} in the part's cost" if w else "",
                strength=max(0.0, (w or 0.1) * ((asked or 0) - chg)) if asked else max(0.0, -(w or 0.1) * chg),
            )
        )
    if weights and asked:
        out.append(
            Claim(
                key="summary:indices",
                kind="summary",
                ids=[],
                figure=round(impact, 1),
                favourable=impact < asked,
                sentence=f"Weighted with the cost structure of this part, the index movements explain about "
                f"{impact:+.1f}% on the price - not {asked:g}%.",
                note="no ID: our own reasoning, not a checked claim",
            )
        )

    # 2. A letter that gives less notice than the contract requires.
    if trigger and trigger.get("days") is not None:
        ctr = next((r for r in case.get("refs", []) if r.startswith("ctr:") and "#" not in r), None)
        cf = _fact(package, case, ctr) if ctr else None
        if cf and cf.get("days") and trigger["days"] < cf["days"]:
            out.append(
                Claim(
                    key="notice",
                    kind="notice",
                    ids=[case["trigger_doc"], ctr],
                    figure=trigger["days"],
                    sentence=f"Your letter gives us only {trigger['days']} days of notice "
                    f"({case['trigger_doc']}, {ctr}).",
                    extra=[f"Our contract requires {cf['days']} days."],
                    note="the increase cannot take effect as announced",
                    strength=5.0,
                )
            )

    # 3. Delivery and quality record.
    sc = sorted(
        i
        for i in ([*case.get("refs", [])] + (package.ids(f"sc:{sid.split(':')[1]}@") if package else []))
        if i.startswith(f"sc:{sid.split(':')[1]}@")
    )
    if sc and (row := _fact(package, case, sc[-1])):
        if case.get("type") == "quality" or (row.get("ppm") or 0) >= 1000:
            out.append(
                Claim(
                    key="scorecard",
                    kind="quality",
                    ids=[sc[-1]],
                    figure=row.get("ppm"),
                    favourable=(row.get("ppm") or 0) > 300,
                    sentence=f"Your defect rate over the last four quarters stands at {row.get('ppm')} ppm ({sc[-1]}).",
                    strength=3.0 if case.get("type") == "quality" else 1.0,
                )
            )
        elif row.get("otd_pct") is not None:
            out.append(
                Claim(
                    key="scorecard",
                    kind="delivery",
                    ids=[sc[-1]],
                    figure=row["otd_pct"],
                    favourable=row["otd_pct"] < 95,
                    sentence=f"Your on-time delivery over the last four quarters was {row['otd_pct']:.1f}% ({sc[-1]}).",
                    strength=(95 - row["otd_pct"]) / 5,
                )
            )

    # 4. Competing prices: a rival's offer in this session, or a quote the case points to.
    for oid, price in sorted((rivals or {}).items(), key=lambda kv: kv[1]):
        if their_price is None or price < their_price:
            out.append(
                Claim(
                    key=f"rival:{oid.split('-')[0]}",
                    kind="rival",
                    ids=[oid],
                    figure=price,
                    sentence=f"We hold a competing offer at EUR {price:.2f} per unit ({oid}).",
                    note="reveals that rival's price to this supplier",
                    strength=6.0,
                )
            )
            break
    alt = (case.get("buyer") or {}).get("alternative") or {}
    for ref in [alt.get("ref")] + [r for r in case.get("refs", []) if r.startswith("quote:")]:
        q = _fact(package, case, ref) if ref and ref.startswith("quote:") else None
        if q and q.get("supplier") != sid and q.get("unit_price") and q.get("part") in parts:
            fav = their_price is not None and q["unit_price"] < their_price
            out.append(
                Claim(
                    key=f"quote:{ref}",
                    kind="rival",
                    ids=[ref],
                    figure=q["unit_price"],
                    favourable=fav,
                    sentence=f"We hold a quote from another qualified supplier at EUR {q['unit_price']:.2f} "
                    f"per unit ({ref}).",
                    note="" if fav else "higher than this supplier's price: citing it would weaken us",
                    strength=4.0,
                )
            )
            break

    # 5. Should-cost: only when it leaves the supplier a healthy margin at a lower price.
    for p in parts:
        ref = f"cost:{p.split(':')[1]}"
        if (row := _fact(package, case, ref)) and row.get("unit_cost") and their_price:
            fav = row["unit_cost"] * 1.08 < their_price
            out.append(
                Claim(
                    key="should_cost",
                    kind="should_cost",
                    ids=[ref],
                    figure=row["unit_cost"],
                    favourable=fav,
                    sentence=f"Our should-cost estimate for this part is EUR {row['unit_cost']:.2f} per unit ({ref}).",
                    note="no margin included" if fav else "close to their price: shows they earn little - avoid",
                    strength=3.0,
                )
            )

    # 6. Volume: a growing forecast is a reason to want our business.
    if package:
        for p in parts:
            fcs = package.ids(f"fc:{p.split(':')[1]}@")
            if fcs and (row := _fact(package, case, fcs[-1])) and row.get("change_pct") is not None:
                # Only as growth if the volume did grow: P01's +10.1% sat next to a forecast that fell
                # from 8,200 to 8,150 - a supplier who sees both reads it as overstated.
                before = _fact(package, case, fcs[-2]) if len(fcs) > 1 else None
                grew = not before or (row.get("volume_per_year") or 0) >= (before.get("volume_per_year") or 0)
                out.append(
                    Claim(
                        key="forecast",
                        kind="volume",
                        ids=[fcs[-1]],
                        figure=row["change_pct"],
                        favourable=row["change_pct"] > 0 and grew,
                        sentence=f"Our demand forecast for this part has changed "
                        f"{row['change_pct']:+.1f}% ({fcs[-1]}).",
                        note="growing volume: a carrot, not a threat",
                        strength=1.5,
                    )
                )

    # 7. News about the supplier: true by ID; the model judges whether it helps.
    if package and package.db:
        for r in package.query(
            "SELECT id, headline, topic FROM news WHERE supplier_id = ? ORDER BY date DESC LIMIT 3", (sid,)
        ):
            out.append(
                Claim(
                    key=f"news:{r['id']}",
                    kind="news",
                    ids=[r["id"]],
                    favourable=False,
                    sentence=f"We have followed the news about your company ({r['id']}).",
                    note=f"{r['topic']}: {r['headline']}",
                )
            )
    out.sort(key=lambda c: -c.strength)
    return out


def usable(claims, ledger, sid):
    """The favourable claims not cited yet."""
    return [c for c in claims if c.favourable and not ledger.spent(c, sid)]

